<?php

# @autogenerated
declare(strict_types=1);

namespace Civi\Lughauth\Features\Access\UserGroupMembership\Application\Usecase\Retrieve;

use Psr\EventDispatcher\EventDispatcherInterface;
use Throwable;
use Civi\Lughauth\Shared\Security\Allow;
use Civi\Lughauth\Shared\Exception\UnauthorizedException;
use Civi\Lughauth\Shared\Exception\NotFoundException;
use Civi\Lughauth\Features\Access\UserGroupMembership\Domain\UserGroupMembershipRef;
use Civi\Lughauth\Features\Access\UserGroupMembership\Application\Service\Visibility\UserGroupMembershipVisibilityService;
use Civi\Lughauth\Features\Access\UserGroupMembership\Domain\Gateway\UserGroupMembershipReadGateway;
use Civi\Lughauth\Shared\Observability\LoggerAwareTrait;
use Civi\Lughauth\Shared\Observability\TracerAwareTrait;

class UserGroupMembershipRetrieveUsecase
{
    use LoggerAwareTrait;
    use TracerAwareTrait;

    public function __construct(
        private readonly EventDispatcherInterface $dispatcher,
        private readonly UserGroupMembershipVisibilityService $visibility,
        private readonly UserGroupMembershipReadGateway $reader
    ) {
    }

    public function allowRetrieve(?UserGroupMembershipRef $ref = null): Allow
    {
        $this->logDebug("Check allow of retrieve usecase for User group membership");
        $span = $this->startSpan("Check allow of retrieve usecase for User group membership");
        try {
            $result = $this->dispatcher->dispatch(new UserGroupMembershipRetrieveAllowDecision(Allow::allowed('retrieve', 'Allowed to retrieve by default')));
            return $result->getAllow();
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    public function hiddenFields(?UserGroupMembershipRef $ref = null): array
    {
        $this->logDebug("Check hidden fields usecase for User group membership");
        $span = $this->startSpan("Check hidden fields usecase for User group membership");
        try {
            return $this->visibility->fieldsToHide($ref);
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    public function retrieve(string $uid): UserGroupMembershipRetrieveResult
    {
        $this->logDebug("Run retrieve usecase for User group membership");
        $span = $this->startSpan("Run retrieve usecase for User group membership");
        try {
            $ref = new UserGroupMembershipRef($uid);
            $allow = $this->allowRetrieve($ref);
            if (!$allow->allowed) {
                throw new UnauthorizedException($allow->reason ?? 'Not allowed to retrieve User group membership');
            }
            if (!$result = $this->visibility->retrieveVisible($ref)) {
                throw new NotFoundException($uid);
            }
            $output = $this->visibility->copyWithHidden($this->visibility->prepareVisibleData($result));
            return new UserGroupMembershipRetrieveResult($output);
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
}
